  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../app/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// ------------\n/// Core domain\n/// ------------\n\nmodel Store {\n  id            String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  code          String   @unique\n  name          String\n  uniqueKey     String?\n  companyName   String?\n  corporateName String?\n  timezone      String   @default(\"Europe/Rome\")\n  address       String?\n  city          String?\n  region        String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  operators            Operator[]\n  sales                Sale[]\n  overviewDailyMetrics OverviewDailyMetrics[]\n  overviewRollups      OverviewRollup[]\n  salesStoreDaily      SalesStoreDaily[]\n  salesOperatorDaily   SalesOperatorDaily[]\n  catalogItemDaily     CatalogItemDaily[]\n}\n\nmodel Channel {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  code        String   @unique\n  name        String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  sales             Sale[]\n  salesChannelDaily SalesChannelDaily[]\n}\n\nmodel MenuItem {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  sku       String   @unique\n  name      String\n  category  String?\n  price     Float\n  cost      Float?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  catalogItemDaily CatalogItemDaily[]\n}\n\nmodel Operator {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  code      String   @unique\n  fullName  String\n  role      String?\n  storeId   String?  @db.ObjectId\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store?               @relation(fields: [storeId], references: [id])\n  sales      Sale[]\n  salesDaily SalesOperatorDaily[]\n\n  @@index([storeId])\n}\n\nmodel Sale {\n  id             String     @id @default(auto()) @map(\"_id\") @db.ObjectId\n  storeId        String     @db.ObjectId\n  channelId      String     @db.ObjectId\n  operatorId     String?    @db.ObjectId\n  businessDate   DateTime   @map(\"business_date\")\n  timeSlot       String\n  grossAmount    Float\n  netAmount      Float\n  customersCount Int?\n  documentType   String\n  paymentMethods String[]\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n  items          SaleItem[]\n\n  store    Store     @relation(fields: [storeId], references: [id])\n  channel  Channel   @relation(fields: [channelId], references: [id])\n  operator Operator? @relation(fields: [operatorId], references: [id])\n\n  @@index([storeId, businessDate])\n  @@index([businessDate, channelId])\n  @@index([businessDate, operatorId])\n}\n\ntype SaleItem {\n  itemId     String? @db.ObjectId\n  name       String\n  category   String?\n  quantity   Int\n  unitPrice  Float\n  totalPrice Float\n}\n\n/// -------------------\n/// Aggregated datasets\n/// -------------------\n\nmodel OverviewDailyMetrics {\n  id                String           @id @default(auto()) @map(\"_id\") @db.ObjectId\n  storeId           String           @db.ObjectId\n  businessDate      DateTime         @map(\"business_date\")\n  grossAmount       Float\n  netAmount         Float\n  salesCount        Int\n  avgTicket         Float\n  coversCount       Int\n  avgCover          Float\n  timeSlotBreakdown TimeSlotMetric[] @map(\"time_slot_breakdown\")\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  store Store @relation(fields: [storeId], references: [id])\n\n  @@unique([storeId, businessDate])\n  @@index([businessDate])\n  @@map(\"overview_daily_metrics\")\n}\n\ntype TimeSlotMetric {\n  hour   String\n  sales  Int\n  covers Int\n}\n\nenum OverviewRange {\n  LAST_7_DAYS\n  LAST_30_DAYS\n  LAST_90_DAYS\n  LIFETIME\n}\n\nmodel OverviewRollup {\n  id            String        @id @default(auto()) @map(\"_id\") @db.ObjectId\n  storeId       String        @db.ObjectId\n  range         OverviewRange\n  referenceDate DateTime      @map(\"reference_date\")\n  grossAmount   Float\n  netAmount     Float\n  salesCount    Int\n  avgTicket     Float\n  coversCount   Int\n  avgCover      Float\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  store Store @relation(fields: [storeId], references: [id])\n\n  @@unique([storeId, range, referenceDate])\n  @@map(\"overview_rollup\")\n}\n\nmodel SalesStoreDaily {\n  id                String              @id @default(auto()) @map(\"_id\") @db.ObjectId\n  storeId           String              @db.ObjectId\n  businessDate      DateTime            @map(\"business_date\")\n  salesCount        Int\n  grossAmount       Float\n  avgTicket         Float\n  documentBreakdown DocumentBreakdown[] @map(\"document_breakdown\")\n  createdAt         DateTime            @default(now())\n  updatedAt         DateTime            @updatedAt\n\n  store Store @relation(fields: [storeId], references: [id])\n\n  @@unique([storeId, businessDate])\n  @@map(\"sales_store_daily\")\n}\n\ntype DocumentBreakdown {\n  documentType String\n  salesCount   Int\n  grossAmount  Float\n}\n\nmodel SalesChannelDaily {\n  id           String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  channelId    String   @db.ObjectId\n  businessDate DateTime @map(\"business_date\")\n  salesCount   Int\n  grossAmount  Float\n  avgTicket    Float\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  channel Channel @relation(fields: [channelId], references: [id])\n\n  @@unique([channelId, businessDate])\n  @@map(\"sales_channel_daily\")\n}\n\nmodel SalesOperatorDaily {\n  id           String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  operatorId   String   @db.ObjectId\n  businessDate DateTime @map(\"business_date\")\n  storeId      String?  @db.ObjectId\n  salesCount   Int\n  grossAmount  Float\n  avgTicket    Float\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  operator Operator @relation(fields: [operatorId], references: [id])\n  store    Store?   @relation(fields: [storeId], references: [id])\n\n  @@unique([operatorId, businessDate])\n  @@index([storeId])\n  @@map(\"sales_operator_daily\")\n}\n\nmodel CatalogItemDaily {\n  id           String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  itemId       String   @db.ObjectId\n  storeId      String?  @db.ObjectId\n  businessDate DateTime @map(\"business_date\")\n  quantity     Int\n  grossAmount  Float\n  avgPrice     Float\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  item  MenuItem @relation(fields: [itemId], references: [id])\n  store Store?   @relation(fields: [storeId], references: [id])\n\n  @@unique([itemId, storeId, businessDate])\n  @@map(\"catalog_item_daily\")\n}\n\n// Data-mapper specific tables\nenum IngressSource {\n  POS\n  ERP\n}\n\nmodel IngressEvent {\n  id          String        @id @default(auto()) @map(\"_id\") @db.ObjectId\n  source      IngressSource\n  payload     Json\n  processedAt DateTime?     @map(\"processed_at\")\n  createdAt   DateTime      @default(now())\n\n  @@index([source, createdAt])\n  @@index([processedAt])\n  @@map(\"ingress_events\")\n}\n\nmodel IdempotencyKey {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  key       String   @unique\n  createdAt DateTime @default(now())\n\n  @@map(\"idempotency_keys\")\n}\n",
